-- ===========================================================================
-- Part 2: security (hand-written — review carefully)
--
-- Roles (created by scripts/bootstrap-roles.ts, never by migrations):
--   kenisha_migrator  schema owner; runs migrations only
--   kenisha_app       the API; tenant-scoped via RLS; NOBYPASSRLS
--   kenisha_platform  Super Admin; platform tables only, NO access to tenant data
--
-- Every table has RLS ENABLED and FORCED and only explicit grants. A role with no
-- matching policy sees no rows. A missing tenant context means current_tenant_id()
-- is NULL, which matches nothing (fail closed).
-- ===========================================================================

-- Data checks Prisma cannot express ------------------------------------------
ALTER TABLE "tenants"
  ADD CONSTRAINT "tenants_slug_format" CHECK ("slug" ~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$');
ALTER TABLE "branches"
  ADD CONSTRAINT "branches_country_code_format" CHECK ("country_code" ~ '^[A-Z]{2}$');
ALTER TABLE "subscription_plans"
  ADD CONSTRAINT "subscription_plans_limits_positive" CHECK ("max_branches" > 0 AND "max_staff_users" > 0);
ALTER TABLE "tenant_subscriptions"
  ADD CONSTRAINT "tenant_subscriptions_period_valid" CHECK ("current_period_end" > "current_period_start");

-- Tenant context ---------------------------------------------------------------
-- Reads the transaction-local setting written by withTenant(). NULLIF matters: once a
-- transaction that set it ends, the setting reads as '' (not NULL) for the session.
CREATE FUNCTION "current_tenant_id"() RETURNS uuid
  LANGUAGE sql STABLE
  SET search_path = pg_catalog
  AS $$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid $$;

REVOKE ALL ON FUNCTION "current_tenant_id"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "current_tenant_id"() TO kenisha_app;

-- tenants (platform-owned) -------------------------------------------------------
ALTER TABLE "tenants" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenants" FORCE ROW LEVEL SECURITY;

GRANT SELECT ON "tenants" TO kenisha_app;
-- Hospital admins may rename their hospital and choose the branch scope mode — nothing else.
GRANT UPDATE ("name", "branch_scope_mode", "updated_at") ON "tenants" TO kenisha_app;
GRANT SELECT, INSERT, UPDATE ON "tenants" TO kenisha_platform;

CREATE POLICY "tenants_app_own_row" ON "tenants" TO kenisha_app
  USING ("id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("id" = (SELECT "current_tenant_id"()));
CREATE POLICY "tenants_platform_all" ON "tenants" TO kenisha_platform
  USING (true) WITH CHECK (true);

-- branches (tenant-owned; NOT visible to the platform role) ------------------------
ALTER TABLE "branches" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "branches" FORCE ROW LEVEL SECURITY;

-- No DELETE: branches are deactivated (is_active = false) to preserve history.
GRANT SELECT, INSERT ON "branches" TO kenisha_app;
GRANT UPDATE ("code", "name", "address_line1", "address_line2", "city", "state", "postal_code",
              "country_code", "phone", "is_active", "updated_at") ON "branches" TO kenisha_app;

CREATE POLICY "branches_tenant_isolation" ON "branches" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));

-- subscription_plans (platform-owned; readable by every tenant) -------------------
ALTER TABLE "subscription_plans" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "subscription_plans" FORCE ROW LEVEL SECURITY;

GRANT SELECT ON "subscription_plans" TO kenisha_app;
GRANT SELECT, INSERT, UPDATE ON "subscription_plans" TO kenisha_platform;

CREATE POLICY "subscription_plans_app_read" ON "subscription_plans" FOR SELECT TO kenisha_app
  USING (true);
CREATE POLICY "subscription_plans_platform_all" ON "subscription_plans" TO kenisha_platform
  USING (true) WITH CHECK (true);

-- tenant_subscriptions (platform-managed; tenant reads its own) --------------------
ALTER TABLE "tenant_subscriptions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant_subscriptions" FORCE ROW LEVEL SECURITY;

GRANT SELECT ON "tenant_subscriptions" TO kenisha_app;
GRANT SELECT, INSERT, UPDATE ON "tenant_subscriptions" TO kenisha_platform;

CREATE POLICY "tenant_subscriptions_app_own" ON "tenant_subscriptions" FOR SELECT TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()));
CREATE POLICY "tenant_subscriptions_platform_all" ON "tenant_subscriptions" TO kenisha_platform
  USING (true) WITH CHECK (true);
